+/* Latest News timeline (rendered by home-news.js from assets/data/news.json).
+   A vertical rail runs down the left; month headers sit on it as filled dots
+   and each entry hangs off it as an emoji chip. The rail is a single
+   pseudo-element on the list so it stays continuous across hidden rows. */
+/* The timeline sits inside a full-width card; give it a little more room than
+   the default card padding on wide screens. */
+@media (min-width: 768px) {
+  .lf-tl-card {
+    padding: 2rem 2.5rem;
+  }
 }

-.lf-newsbar-row {
