-  gap: 1rem;
-  min-height: 3.75rem;
-  font-size: .9375rem;
+.lf-tl {
+  --tl-x: 1.25rem;
+  /* rail centre, measured from the list's left edge */
+  list-style: none;
+  margin: 0;
+  padding: 0;
+  position: relative;
 }

-.lf-newsbar-tag {
-  flex: none;
