+  min-width: 0;
+  padding-top: .3rem;
+  font-size: .95rem;
+  line-height: 1.6;
+  color: #374151;
+  overflow-wrap: anywhere;
+}
+
+.lf-tl-text b {
+  color: #111827;
+  font-weight: 650;
+}
+
+.lf-tl-link {
+  margin-left: .25rem;
+  white-space: nowrap;
   font-weight: 600;
   color: #4F46E5;
   text-decoration: none;
 }

-.lf-newsbar-all:hover {
