+  box-shadow: 0 0 0 4px #0f172a, 0 0 0 5px rgba(129, 140, 248, .5);
+}
+
+.dark .lf-tl-ico {
+  background: rgba(49, 46, 129, .45);
+  border-color: rgba(99, 102, 241, .45);
+  box-shadow: 0 0 0 3px #0f172a;
+}
+
+.dark .lf-tl-text {
+  color: #d1d5db;
+}
+
+.dark .lf-tl-text b {
+  color: #f9fafb;
 }

-.dark .lf-newsbar-link:hover .lf-newsbar-title,
-.dark .lf-newsbar-all {
+.dark .lf-tl-link,
+.dark .lf-tl-more {
   color: #A5B4FC;
 }

-.dark .lf-newsbar-date {
-  color: #9ca3af;
+.dark .lf-tl-more {
+  border-color: rgba(99, 102, 241, .45);
+}
+
+.dark .lf-tl-more:hover {
+  background: rgba(49, 46, 129, .4);
 }

-/* Narrow screens: drop the date and the trailing link so the strip stays on
-   one line instead of wrapping into a two-line block. */
 @media (max-width: 640px) {
+  .lf-tl {
+    --tl-x: 1rem;
+  }

-  .lf-newsbar-date,
-  .lf-newsbar-all {
-    display: none;
+  .lf-tl-month {
+    padding-left: calc(var(--tl-x) + 1.5rem);
+  }
+
+  .lf-tl-item {
+    gap: .625rem;
+  }
+
+  .lf-tl-text {
+    font-size: .9rem;
   }
 }

