+/* ===== Code blocks: one light style site-wide, using the same indigo tint as the page tint sections (#F7F8FF) =====
+   Covers Prism blocks, blog .prose-lf blocks and the Quick Start .cmd-block.
+   Dark mode keeps the dark block. style.css forces the Prism background with
+   !important, so the light override needs it too. */
+:root:not(.dark) pre[class*="language-"] {
+  background: #F7F8FF !important;
+  border: 1px solid #E0E7FF !important;
+}
+
+:root:not(.dark) .prose-lf pre,
+:root:not(.dark) .cmd-block {
+  background: #F7F8FF;
+  color: #24292F;
+  border: 1px solid #E0E7FF;
+}
+
+:root:not(.dark) code[class*="language-"],
+:root:not(.dark) pre[class*="language-"] {
+  color: #24292F;
+  text-shadow: none;
+}
+
+:root:not(.dark) pre .token.comment,
+:root:not(.dark) pre .token.prolog,
+:root:not(.dark) pre .token.doctype,
+:root:not(.dark) pre .token.cdata {
+  color: #6E7781;
+}
+
+:root:not(.dark) pre .token.punctuation {
+  color: #24292F;
+}
+
+:root:not(.dark) pre .token.tag,
+:root:not(.dark) pre .token.attr-name,
+:root:not(.dark) pre .token.namespace,
+:root:not(.dark) pre .token.selector,
+:root:not(.dark) pre .token.deleted {
+  color: #116329;
+}
+
+:root:not(.dark) pre .token.function,
+:root:not(.dark) pre .token.function-name {
+  color: #8250DF;
+}
+
+:root:not(.dark) pre .token.boolean,
+:root:not(.dark) pre .token.number,
+:root:not(.dark) pre .token.constant,
+:root:not(.dark) pre .token.symbol,
+:root:not(.dark) pre .token.operator,
+:root:not(.dark) pre .token.entity,
+:root:not(.dark) pre .token.url {
+  color: #0550AE;
+  background: none;
+}
+
+:root:not(.dark) pre .token.property,
+:root:not(.dark) pre .token.class-name {
+  color: #953800;
+}
+
+:root:not(.dark) pre .token.keyword,
+:root:not(.dark) pre .token.builtin,
+:root:not(.dark) pre .token.atrule,
+:root:not(.dark) pre .token.important {
+  color: #CF222E;
+}
+
+:root:not(.dark) pre .token.string,
+:root:not(.dark) pre .token.char,
+:root:not(.dark) pre .token.attr-value,
+:root:not(.dark) pre .token.regex,
+:root:not(.dark) pre .token.variable,
+:root:not(.dark) pre .token.inserted {
+  color: #0A3069;
+}
+
+:root:not(.dark) .cmd-block .prompt {
+  color: #8250DF;
+}
+
+:root:not(.dark) .cmd-block .flag {
+  color: #953800;
+}
+
+:root:not(.dark) .cmd-block .val {
+  color: #116329;
+}
+
+:root:not(.dark) .cmd-block .cmt {
+  color: #6E7781;
+}
+
+:root:not(.dark) pre .copy-btn {
+  background: #fff;
+  color: #475569;
+  border-color: #E0E7FF;
+}
+
+:root:not(.dark) pre .copy-btn:hover {
+  background: #EEF2FF;
+}
+
+/* Back link shared by blog posts and project pages: chevron icon + text. */
+.back-link {
+  display: inline-flex;
+  align-items: center;
+  gap: .3rem;
+  font-size: .875rem;
+  font-weight: 500;
+  color: #6B7280;
+  transition: color .15s ease;
+}
+
+.back-link svg {
+  width: 1rem;
+  height: 1rem;
+  flex: none;
+  transition: transform .15s ease;
+}
+
+.back-link:hover {
+  color: #4F46E5;
+}
+
+.back-link:hover svg {
+  transform: translateX(-2px);
+}
+
+.dark .back-link {
+  color: #9CA3AF;
+}
+
+.dark .back-link:hover {
+  color: #A5B4FC;
+}

@@ -0,0 +1,818 @@
+/* LoongForge-VLDA project page. Loaded only by vlda.html, on top of style.css.
+   Everything is prefixed .vl- so it cannot leak into other pages. */
+
+/* ---- Hero extras ---- */
+.vl-authors {
+  display: flex;
+  flex-wrap: wrap;
+  justify-content: center;
+  gap: .25rem 1.1rem;
+  font-weight: 600;
+  font-size: 1rem;
+}
+
+.vl-authors sup {
+  font-size: .68em;
+  font-weight: 500;
+  margin-left: .1em;
+  color: #6366F1;
+}
+
+.dark .vl-authors sup {
+  color: #A5B4FC;
+}
+
+.vl-affil {
+  margin-top: .6rem;
+  font-size: .85rem;
+  color: #6B7280;
+}
+
+.dark .vl-affil {
+  color: #9CA3AF;
+}
+
+/* Contribution / corresponding-author marks sit on their own line under the affiliations. */
+.vl-affil.vl-affil-note {
+  margin-top: .2rem;
+}
+
+.vl-soon {
+  display: inline-flex;
+  align-items: center;
+  gap: .5rem;
+  padding: .85rem 1.6rem;
+  border-radius: 9999px;
+  font-weight: 700;
+  color: #9CA3AF;
+  background: transparent;
+  border: 1.5px dashed #CBD5E1;
+  cursor: not-allowed;
+}
+
+.dark .vl-soon {
+  border-color: rgba(255, 255, 255, .2);
+  color: #6B7280;
+}
+
+/* Anchored sections must clear the sticky navbar */
+.vl-sec {
+  scroll-margin-top: 5.5rem;
+}
+
+/* ---- Video ---- */
+.vl-video {
+  border-radius: 1.25rem;
+  overflow: hidden;
+  background: #0b1020;
+  border: 1px solid #E9EBF5;
+  box-shadow: 0 24px 60px -28px rgba(79, 70, 229, .45);
+}
+
+.dark .vl-video {
+  border-color: #1f2937;
+  box-shadow: none;
+}
+
+.vl-video video {
+  display: block;
+  width: 100%;
+  height: auto;
+  aspect-ratio: 16 / 9;
+  background: #000;
+}
+
+/* ---- Figures ---- */
+.vl-fig {
+  margin: 0;
+}
+
+.vl-fig-frame {
+  display: block;
+  border-radius: 1rem;
+  background: #fff;
+  border: 1px solid #E9EBF5;
+  padding: .75rem;
+  overflow: hidden;
+}
+
+.dark .vl-fig-frame {
+  border-color: #1f2937;
+  background: #f8fafc;
+}
+
+.vl-fig-frame img {
+  display: block;
+  width: 100%;
+  height: auto;
+}
+
+.vl-fig figcaption {
+  margin-top: .85rem;
+  font-size: .875rem;
+  line-height: 1.6;
+  color: #4B5563;
+}
+
+.dark .vl-fig figcaption {
+  color: #9CA3AF;
+}
+
+.vl-fig figcaption a {
+  white-space: nowrap;
+  color: #4F46E5;
+  font-weight: 600;
+}
+
+.dark .vl-fig figcaption a {
+  color: #A5B4FC;
+}
+
+/* ---- Understand -> Transition -> Execute flow ---- */
+.vl-flow {
+  display: grid;
+  grid-template-columns: 1fr auto 1fr auto 1fr;
+  align-items: stretch;
+  gap: .75rem;
+}
+
+.vl-node {
+  border-radius: 1.1rem;
+  padding: 1.1rem 1.2rem;
+  background: #fff;
+  border: 1px solid #E9EBF5;
+}
+
+.dark .vl-node {
+  background: #0f172a;
+  border-color: #1f2937;
+}
+
+.vl-node b {
+  display: block;
+  font-size: 1.05rem;
+  margin-bottom: .25rem;
+}
+
+.vl-node span {
+  font-size: .85rem;
+  line-height: 1.55;
+  color: #4B5563;
+}
+
+.dark .vl-node span {
+  color: #9CA3AF;
+}
+
+.vl-node.vl-delta {
+  border-color: transparent;
+  background:
+    linear-gradient(#fff, #fff) padding-box,
+    var(--lf-grad) border-box;
+  border: 2px solid transparent;
+  box-shadow: 0 16px 36px -22px rgba(124, 58, 237, .6);
+}
+
+.dark .vl-node.vl-delta {
+  background:
+    linear-gradient(#0f172a, #0f172a) padding-box,
+    var(--lf-grad) border-box;
+}
+
+.vl-arrow {
+  align-self: center;
+  font-size: 1.5rem;
+  color: #A5B4FC;
+}
+
+@media (max-width: 768px) {
+  .vl-flow {
+    grid-template-columns: 1fr;
+  }
+
+  .vl-arrow {
+    transform: rotate(90deg);
+    justify-self: center;
+  }
+}
+
+/* ---- Numbered mechanism cards ---- */
+.vl-num {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  width: 2.1rem;
+  height: 2.1rem;
+  border-radius: 9999px;
+  font-weight: 800;
+  color: #fff;
+  background: var(--lf-grad);
+  margin-bottom: .9rem;
+}
+
+.vl-abbr {
+  font-family: 'JetBrains Mono', ui-monospace, monospace;
+  font-size: .78rem;
+  font-weight: 500;
+  color: #6366F1;
+  letter-spacing: .02em;
+}
+
+.dark .vl-abbr {
+  color: #A5B4FC;
+}
+
+/* ---- Two-stage training ---- */
+.vl-stage {
+  border-radius: 1.1rem;
+  padding: 1.25rem 1.4rem;
+  background: #F7F8FF;
+  border: 1px solid #E0E7FF;
+}
+
+.dark .vl-stage {
+  background: rgba(99, 102, 241, .08);
+  border-color: rgba(99, 102, 241, .25);
+}
+
+.vl-stage p b {
+  color: #111827;
+}
+
+.dark .vl-stage p b {
+  color: #F3F4F6;
+}
+
+.vl-stage code {
+  display: block;
+  margin-top: .6rem;
+  padding: .55rem .75rem;
+  border-radius: .6rem;
+  font-family: 'JetBrains Mono', ui-monospace, monospace;
+  font-size: .8rem;
+  background: #fff;
+  border: 1px solid #E0E7FF;
+  overflow-x: auto;
+}
+
+.dark .vl-stage code {
+  background: #0b1020;
+  border-color: #1f2937;
+}
+
+/* ---- Result tables ---- */
+.vl-tablewrap {
+  overflow-x: auto;
+  border-radius: 1rem;
+  border: 1px solid #E9EBF5;
+  background: #fff;
+}
+
+.dark .vl-tablewrap {
+  border-color: #1f2937;
+  background: #0f172a;
+}
+
+.vl-table {
+  width: 100%;
+  min-width: 36rem;
+  border-collapse: collapse;
+  font-size: .875rem;
+  font-variant-numeric: tabular-nums;
+}
+
+.vl-table th,
+.vl-table td {
+  padding: .6rem .8rem;
+  text-align: right;
+  white-space: nowrap;
+  border-bottom: 1px solid #EEF0F7;
+}
+
+.dark .vl-table th,
+.dark .vl-table td {
+  border-bottom-color: #1f2937;
+}
+
+/* Few-column tables sit in a half-width column: drop the wide-table floor and
+   tighten the padding so they fit without a horizontal scroll. */
+.vl-table.vl-compact {
+  min-width: 0;
+}
+
+.vl-table.vl-compact th,
+.vl-table.vl-compact td {
+  padding: .6rem .55rem;
+}
+
+.vl-table th:first-child,
+.vl-table td:first-child {
+  text-align: left;
+  position: sticky;
+  left: 0;
+  background: #fff;
+}
+
+.dark .vl-table td:first-child {
+  background: #0f172a;
+}
+
+.vl-table thead th:first-child {
+  background: #F9FAFB;
+}
+
+.dark .vl-table thead th:first-child {
+  background: #111827;
+}
+
+.vl-table thead th {
+  font-weight: 600;
+  font-size: .78rem;
+  color: #6B7280;
+  background: #F9FAFB;
+}
+
+.dark .vl-table thead th {
+  color: #9CA3AF;
+  background: #111827;
+}
+
+.vl-table tbody tr:last-child td {
+  border-bottom: 0;
+}
+
+.vl-table tr.vl-ours td {
+  font-weight: 700;
+  color: #3730A3;
+  background: #EEF2FF;
+}
+
+.dark .vl-table tr.vl-ours td {
+  color: #E0E7FF;
+  background: rgba(99, 102, 241, .18);
+}
+
+.vl-table td.vl-best {
+  font-weight: 700;
+}
+
+.vl-note {
+  margin-top: .75rem;
+  font-size: .82rem;
+  line-height: 1.6;
+  color: #6B7280;
+}
+
+.dark .vl-note {
+  color: #9CA3AF;
+}
+
+/* ---- Real-world bars ---- */
+.vl-bar {
+  display: grid;
+  grid-template-columns: 6.5rem 1fr 3rem;
+  align-items: center;
+  gap: .6rem;
+  font-size: .82rem;
+  margin-top: .45rem;
+}
+
+.vl-bar>span:first-child {
+  color: #6B7280;
+  white-space: nowrap;
+}
+
+.dark .vl-bar>span:first-child {
+  color: #9CA3AF;
+}
+
+.vl-bar>span:last-child {
+  text-align: right;
+  font-weight: 600;
+  font-variant-numeric: tabular-nums;
+}
+
+.vl-bar i {
+  display: block;
+  height: .55rem;
+  border-radius: 9999px;
+  background: #CBD5E1;
+}
+
+.dark .vl-bar i {
+  background: #475569;
+}
+
+.vl-bar.vl-b-ours i {
+  background: var(--lf-grad);
+}
+
+.vl-bar.vl-b-ours>span {
+  color: #4338CA;
+  font-weight: 700;
+}
+
+.dark .vl-bar.vl-b-ours>span {
+  color: #C7D2FE;
+}
+
+.vl-bar-track {
+  height: .55rem;
+  border-radius: 9999px;
+  background: #F1F5F9;
+  overflow: hidden;
+}
+
+.dark .vl-bar-track {
+  background: #1e293b;
+}
+
+/* ---- Ablation tiles ---- */
+.vl-abl {
+  display: flex;
+  flex-direction: column;
+  gap: .35rem;
+}
+
+.vl-abl-num {
+  display: flex;
+  align-items: baseline;
+  gap: .5rem;
+  font-variant-numeric: tabular-nums;
+}
+
+.vl-abl-num s {
+  color: #9CA3AF;
+  font-size: .95rem;
+}
+
